                if c == "time":
                    t = parse_time(x) - tz
                elif c in RANGES:
                    vals[c] = convert(c, units.get(c, CANON[c]), x)
            if t is None:
                continue
            intervals[station] = interval
            k = (station, t)
            old = rows.get(k)
            if old is None or upload > old[0]:
                rows[k] = (upload, vals)
    return rows, syncs, intervals


def hour_of(t):
    return -((-t) // 3600) * 3600


def iso(t):
    return "%04d-%02d-%02dT%02d:00:00Z" % _ymdh(t)


def _ymdh(t):
    import time
    g = time.gmtime(t)
    return g.tm_year, g.tm_mon, g.tm_mday, g.tm_hour


def num(x):
    x = round(float(x), 2)
    return x + 0.0


def main(indir, outfile):
    rows, syncs, intervals = read_dumps(indir)
    by_station = {}
    for (st, t), (_, vals) in rows.items():
        by_station.setdefault(st, []).append((t, vals))
    sync_by = {}
    for (st, t), (_, off) in syncs.items():
        sync_by.setdefault(st, []).append((t, off))

    stations = []
    for st in sorted(by_station):
        interval = intervals[st]
        pts = sorted(sync_by.get(st, []))
        ts = [p[0] for p in pts]

        def offset(t):
            if not pts:
                return 0
            if t <= ts[0]:
                return pts[0][1]
            if t >= ts[-1]:
                return pts[-1][1]
            i = bisect.bisect_left(ts, t)
            if ts[i] == t:
                return pts[i][1]
            t1, o1 = pts[i - 1]
            t2, o2 = pts[i]
            return (o1 * (t2 - t1) + (o2 - o1) * (t - t1)) // (t2 - t1)

        recs = sorted(((t + offset(t), t, vals) for t, vals in by_station[st]),
                      key=lambda r: (r[0], r[1]))
        first = hour_of(recs[0][0])
        last = hour_of(recs[-1][0])

        # rain increments
        incr = {}  # index in recs -> increment
        prev = None
        for i, (ct, _, vals) in enumerate(recs):
            r = vals.get("rain")
            if r is None:
                continue
            if prev is not None and (ct - prev[0]) * 2 <= 5 * interval:
                p = prev[1]
                incr[i] = r - p if r >= p else r
            prev = (ct, r)

        acc = {}  # hour -> quantity -> state
        for i, (ct, _, vals) in enumerate(recs):
            h = hour_of(ct)
            a = acc.setdefault(h, {q: [0, F(0)] for q in QUANTITIES})
            for q in QUANTITIES:
                v = vals.get(q)
                if v is None:
                    continue
                a[q][0] += 1
                if q == "rain":
                    a[q][1] += incr.get(i, 0)
                elif q != "wdir":
                    a[q][1] += v
            d = vals.get("wdir")
            s = vals.get("wspd")
            if d is not None and s is not None and s > 0:
                vec = a.setdefault("vec", [0.0, 0.0, 0])
                rad = math.radians(float(d))
                vec[0] += math.sin(rad)
                vec[1] += math.cos(rad)
                vec[2] += 1

        hours = []
        t = first
        while t <= last:
            a = acc.get(t)
            entry = {"hour": iso(t)}
            for q in QUANTITIES:
                n = a[q][0] if a else 0
                value = None
                if a and n * 4 * interval >= 3 * 3600:
                    if q in ("temp", "rh", "pres", "wspd"):
                        value = num(a[q][1] / n)
                    elif q == "rain":
                        value = num(a[q][1])
                    else:
                        vec = a.get("vec")
                        if vec and vec[2] and math.hypot(vec[0], vec[1]) > 1e-9:
                            ang = math.degrees(math.atan2(vec[0], vec[1])) % 360.0
                            value = num(ang)
                            if value >= 360:
                                value = 0.0
                entry[q] = {"value": value, "n": n}
            hours.append(entry)
            t += 3600
        stations.append({"station": st, "interval_s": int(interval), "hours": hours})

    with open(outfile, "w", encoding="utf-8") as fh:
        json.dump({"stations": stations}, fh, indent=1)
        fh.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
